(4900511, 710927, 97339, '<td valign="top">What a brilliant photo! The symmetry is perfect, exposure right on and the colors work together well. I love that the little girl is not looking at the camera - that would have been too posed. Excellent shot!</td>', 'What a brilliant photo! The symmetry is perfect, exposure right on and the colors work together well. I love that the little girl is not looking at the camera - that would have been too posed. Excellent shot!', '2008-08-20 14:38:40.000000', NULL, 1),
(4900529, 712335, 97339, '<td valign="top">Nice photo, I like the composition - maybe you could crop some off the top. I think that there is too much of the trees and it detracts from the main subject -the door. I like the pathway leading up to the door and the girl in the shot is a nice touch</td>', 'Nice photo, I like the composition - maybe you could crop some off the top. I think that there is too much of the trees and it detracts from the main subject -the door. I like the pathway leading up to the door and the girl in the shot is a nice touch', '2008-08-20 14:45:32.000000', NULL, 1),
(4900541, 711252, 97339, '<td valign="top">I like it very much!!VERY VERY MUCH! What a great shot - composition, exposure everything. Well done!</td>', 'I like it very much!!VERY VERY MUCH! What a great shot - composition, exposure everything. Well done!', '2008-08-20 14:53:39.000000', NULL, 1),
(4900546, 711265, 97339, '<td valign="top">Nice shot - the shallow DOF works well. Nice focus and detail!</td>', 'Nice shot - the shallow DOF works well. Nice focus and detail!', '2008-08-20 14:55:14.000000', NULL, 1),
