(4901057, 712257, 15711, '<td valign="top">I really love the composition.  Great duality with the metal grates too. Great contrast.</td>', 'I really love the composition.  Great duality with the metal grates too. Great contrast.', '2008-08-20 19:24:29.000000', NULL, 1),
(4901065, 710501, 15711, '<td valign="top">This is reminiscent of a 20''s artist - I like it.</td>', 'This is reminiscent of a 20''s artist - I like it.', '2008-08-20 19:29:33.000000', NULL, 1),
(4901071, 712320, 15711, '<td valign="top">Really interesting.  This has a lot more to offer than ONE - which I''m sure is ironic. I love that there are six windows, the reflections, the tilt and the hint of brick. Artfully presented.</td>', 'Really interesting.  This has a lot more to offer than ONE - which I''m sure is ironic. I love that there are six windows, the reflections, the tilt and the hint of brick. Artfully presented.', '2008-08-20 19:32:44.000000', NULL, 1),
(4901076, 710830, 15711, '<td valign="top">Nice use of duality (the bike wheels, the two rectangular shapes of the window and the statue thingy). I am thinking if might be fun to play with this in BW too.  May not work, but I always like to compare.  NICE</td>', 'Nice use of duality (the bike wheels, the two rectangular shapes of the window and the statue thingy). I am thinking if might be fun to play with this in BW too.  May not work, but I always like to compare.  NICE', '2008-08-20 19:35:39.000000', NULL, 1),
(4901082, 711369, 15711, '<td valign="top">I really like the composition but wish that the door were maybe not quite so centered. Great use of complementary colors. Was this shot on a cloudy day?  They seem a touch muddy, but not enough to really detract.  The texture of the wall is fantastic. Great repetition of the rectangular shapes throughout.</td>', 'I really like the composition but wish that the door were maybe not quite so centered. Great use of complementary colors. Was this shot on a cloudy day?  They seem a touch muddy, but not enough to really detract.  The texture of the wall is fantastic. Great repetition of the rectangular shapes throughout.', '2008-08-20 19:39:18.000000', NULL, 1),
(4901085, 711037, 15711, '<td valign="top">I love the composition but find the selective saturation of the door a detraction from the overall feel of the beautiful scene.  This is just a matter of taste though.  You like vanilla: I like chocolate. :~)</td>', 'I love the composition but find the selective saturation of the door a detraction from the overall feel of the beautiful scene.  This is just a matter of taste though.  You like vanilla: I like chocolate. :~)', '2008-08-20 19:41:35.000000', NULL, 1),
(4901087, 711252, 15711, '<td valign="top">Nicely done.  I really love how the line leads us to the "glowing " door.  As a nut for BW, I just wonder what that would look like. :~)</td>', 'Nicely done.  I really love how the line leads us to the "glowing " door.  As a nut for BW, I just wonder what that would look like. :~)', '2008-08-20 19:43:39.000000', NULL, 1),
(4901091, 711729, 15711, '<td valign="top">I like it.  Nice different approach with more than just a door.</td>', 'I like it.  Nice different approach with more than just a door.', '2008-08-20 19:44:42.000000', NULL, 1),
(4901094, 711406, 15711, '<td valign="top">Yummy DOF.  The green and contrasting rust really suits my fancy.</td>', 'Yummy DOF.  The green and contrasting rust really suits my fancy.', '2008-08-20 19:46:48.000000', NULL, 1),
(4901101, 712300, 72670, '<td valign="top">This has such great colours but you missed it in the process. It looks a little grey to me.</td>', 'This has such great colours but you missed it in the process. It looks a little grey to me.', '2008-08-20 19:50:06.000000', NULL, 1),
(4901102, 710707, 15711, '<td valign="top">You had me with the bunny.</td>', 'You had me with the bunny.', '2008-08-20 19:50:22.000000', NULL, 1),
(4901108, 711387, 15711, '<td valign="top">I really love the black/green ratio.  I think the frame is a bit of a distraction. The slight tilt kind of bugs me but that''s just my taste.  I love the door and the vines themselves. :~)</td>', 'I really love the black/green ratio.  I think the frame is a bit of a distraction. The slight tilt kind of bugs me but that''s just my taste.  I love the door and the vines themselves. :~)', '2008-08-20 19:52:44.000000', NULL, 1),
(4901113, 711737, 15711, '<td valign="top">Nice composition. Love the blue and yellow.  Great natural framing.</td>', 'Nice composition. Love the blue and yellow.  Great natural framing.', '2008-08-20 19:56:14.000000', NULL, 1),
(4901114, 712305, 15711, '<td valign="top">I really like it.  I might up contrast a smidge, but terrific composition and eye for finding it.</td>', 'I really like it.  I might up contrast a smidge, but terrific composition and eye for finding it.', '2008-08-20 19:57:54.000000', NULL, 1),
(4901125, 711874, 15711, '<td valign="top">This is perfect. Light, contrast, focus, line, symmetry. 10</td>', 'This is perfect. Light, contrast, focus, line, symmetry. 10', '2008-08-20 20:03:43.000000', NULL, 1),
(4901156, 712248, 92864, '<td valign="top">One of my favorites. Hope this does well for you.</td>', 'One of my favorites. Hope this does well for you.', '2008-08-20 20:26:08.000000', NULL, 1),
(4901160, 712240, 92864, '<td valign="top">I like the idea and I think it works. Good luck.</td>', 'I like the idea and I think it works. Good luck.', '2008-08-20 20:28:30.000000', NULL, 1),
(4901161, 711874, 92864, '<td valign="top">Nice composition. Looks super-crisp. Congrats.</td>', 'Nice composition. Looks super-crisp. Congrats.', '2008-08-20 20:28:53.000000', NULL, 1),
