(4901193, 711387, 94265, '<td valign="top">I don''t care for the border on this one but otherwise, very nice.</td>', 'I don''t care for the border on this one but otherwise, very nice.', '2008-08-20 21:06:02.000000', NULL, 1),
(4901197, 710604, 94265, '<td valign="top">Nice shot but a bit too dark.</td>', 'Nice shot but a bit too dark.', '2008-08-20 21:08:27.000000', NULL, 1),
