(4906489, 711406, 54228, '<td valign="top">Great use of depth of field. I bet the detail comes to life in a larger version. Nice.</td>', 'Great use of depth of field. I bet the detail comes to life in a larger version. Nice.', '2008-08-23 16:42:36.000000', NULL, 1),
(4906490, 711304, 54228, '<td valign="top">This is a great way to add a little interest. Good composition.</td>', 'This is a great way to add a little interest. Good composition.', '2008-08-23 16:43:30.000000', NULL, 1),
(4906491, 710472, 54228, '<td valign="top">This looks like an old slide, nice effect. For the challenge I may have focussed on the door just a tad more. On its own though, this feels like something you might show your kids 10 years down the track, good shot!</td>', 'This looks like an old slide, nice effect. For the challenge I may have focussed on the door just a tad more. On its own though, this feels like something you might show your kids 10 years down the track, good shot!', '2008-08-23 16:44:50.000000', NULL, 1),
(4906494, 712312, 54228, '<td valign="top">Nice toning. My eye keeps leading me up to the sign, which I like, as many of the images in this challenge have had no point for your eye to rest.</td>', 'Nice toning. My eye keeps leading me up to the sign, which I like, as many of the images in this challenge have had no point for your eye to rest.', '2008-08-23 16:46:55.000000', NULL, 1),
