(4907027, 712138, 54228, '<td valign="top">You lucky, lucky person! I''d love to watch these guys go! Wonderful capture! I''d perhaps have bumped the contrast up a little in the colours on this one.</td>', 'You lucky, lucky person! I''d love to watch these guys go! Wonderful capture! I''d perhaps have bumped the contrast up a little in the colours on this one.', '2008-08-24 00:42:52.000000', NULL, 1),
(4907029, 712169, 54228, '<td valign="top">Wow, nice exposure!</td>', 'Wow, nice exposure!', '2008-08-24 00:43:17.000000', NULL, 1),
